#!/usr/bin/env python3
"""Verify the SHA-256 manifest without modifying a release or extracting a ZIP.

This verifies consistency of the bytes in the artifact. Since SHA256SUMS.txt
is shipped alongside those bytes, it is not an external signature or a
substitute for a trusted distribution channel.
"""
from __future__ import annotations

import argparse
import hashlib
import re
import stat
import sys
from pathlib import Path, PurePosixPath
from zipfile import ZipFile

EXCLUDE_NAMES = frozenset({'SHA256SUMS.txt'})
IGNORED_PARTS = frozenset({
    '.git', '.pytest_cache', '__pycache__', '.venv', 'build',
    'gmri_dottie_hill.egg-info',
})
HEX = re.compile(r'^[a-f0-9]{64}$')


class ReleaseIntegrityError(ValueError):
    """Artifact is incomplete, modified, or not safe to verify."""


def valid_relative_path(name: str) -> str:
    if not name or '\\' in name or '\x00' in name or name.startswith('/'):
        raise ReleaseIntegrityError(f'unsafe manifest path: {name!r}')
    posix = PurePosixPath(name)
    if any(p in ('', '.', '..') for p in name.split('/')) or str(posix) != name:
        raise ReleaseIntegrityError(f'unsafe manifest path: {name!r}')
    return name


def parse_manifest(raw: bytes) -> dict[str, str]:
    try:
        lines = raw.decode('utf-8').splitlines()
    except UnicodeDecodeError as exc:
        raise ReleaseIntegrityError('manifest must be UTF-8') from exc
    entries: dict[str, str] = {}
    for i, line in enumerate(lines, 1):
        if not line or len(line) < 67 or line[64:66] != '  ':
            raise ReleaseIntegrityError(f'invalid SHA256SUMS entry on line {i}')
        fingerprint, name = line[:64], line[66:]
        if not HEX.fullmatch(fingerprint):
            raise ReleaseIntegrityError(f'invalid SHA-256 digest on line {i}')
        valid_relative_path(name)
        if name in EXCLUDE_NAMES or name in entries:
            raise ReleaseIntegrityError(f'illegal or duplicate manifest path: {name}')
        entries[name] = fingerprint
    if not entries:
        raise ReleaseIntegrityError('empty SHA256SUMS manifest')
    return entries


def verify_files(files: dict[str, bytes], manifest: bytes) -> int:
    expected = parse_manifest(manifest)
    if 'SHA256SUMS.txt' in files:
        raise ReleaseIntegrityError('manifest must not check itself')
    missing = sorted(set(expected) - set(files))
    extra = sorted(set(files) - set(expected))
    if missing or extra:
        raise ReleaseIntegrityError(f'manifest coverage mismatch: missing={missing[:8]}, extra={extra[:8]}')
    wrong = [name for name, data in files.items()
             if hashlib.sha256(data).hexdigest() != expected[name]]
    if wrong:
        raise ReleaseIntegrityError(f'SHA-256 mismatch: {sorted(wrong)[:8]}')
    return len(files)


def _ignored(name: str) -> bool:
    return any(part in IGNORED_PARTS for part in PurePosixPath(name).parts) or name.endswith(('.pyc', '.pyo'))


def verify_tree(root: Path) -> int:
    root = root.resolve()
    manifest_file = root / 'SHA256SUMS.txt'
    if not manifest_file.is_file() or manifest_file.is_symlink():
        raise ReleaseIntegrityError('missing regular SHA256SUMS.txt')
    files = {}
    for path in root.rglob('*'):
        name = path.relative_to(root).as_posix()
        if _ignored(name):
            continue
        if path.is_symlink():
            raise ReleaseIntegrityError(f'symlink in published release: {name}')
        if path.is_dir():
            continue
        if name != 'SHA256SUMS.txt':
            files[valid_relative_path(name)] = path.read_bytes()
    return verify_files(files, manifest_file.read_bytes())


def verify_archive(archive: Path) -> int:
    with ZipFile(archive) as z:
        names_seen = set()
        files: dict[str, bytes] = {}
        for item in z.infolist():
            name = item.filename
            # The release root must be a single directory and all paths must
            # remain inside it. Validation runs on original names, without
            # extracting or normalizing away '..'.
            if name.endswith('/') and item.is_dir():
                name = name[:-1]
                valid_relative_path(name)
                continue
            valid_relative_path(name)
            if name in names_seen:
                raise ReleaseIntegrityError(f'duplicate ZIP member: {name}')
            names_seen.add(name)
            if stat.S_IFMT(item.external_attr >> 16) == stat.S_IFLNK:
                raise ReleaseIntegrityError(f'symlink ZIP member: {name}')
            if not item.is_dir():
                files[name] = z.read(item)
        if not files:
            raise ReleaseIntegrityError('empty ZIP')
        roots = {name.split('/', 1)[0] for name in files}
        if len(roots) != 1 or any('/' not in name for name in files):
            raise ReleaseIntegrityError('ZIP requires one containing release folder')
        folder = roots.pop() + '/'
        if folder + 'SHA256SUMS.txt' not in files:
            raise ReleaseIntegrityError('ZIP missing root SHA256SUMS.txt')
        manifest = files.pop(folder + 'SHA256SUMS.txt')
        relative = {name[len(folder):]: data for name, data in files.items()}
        if any(_ignored(name) for name in relative):
            raise ReleaseIntegrityError('ZIP contains generated caches or build directories')
        return verify_files(relative, manifest)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description='Read-only ZIP and extracted-tree SHA-256 verification')
    group = parser.add_mutually_exclusive_group()
    group.add_argument('--archive', type=Path, help='Verify a ZIP without extracting it')
    group.add_argument('--root', type=Path, default=Path(__file__).resolve().parents[1],
                       help='Verify an already-extracted source tree')
    args = parser.parse_args(argv)
    try:
        count = verify_archive(args.archive) if args.archive else verify_tree(args.root)
    except (OSError, ReleaseIntegrityError, ValueError, EOFError) as exc:
        print(f'FAIL: {exc}', file=sys.stderr)
        return 2
    print(f'PASS: {count} SHA-256 verified artifact files; not a cryptographic signature or production acceptance')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
