#!/usr/bin/env python3
"""Compile source in memory only. Do not generate __pycache__ inside a release."""
from pathlib import Path
import sys

root = Path(__file__).resolve().parents[1]
files = sorted((root / 'src').rglob('*.py')) + sorted((root / 'scripts').rglob('*.py'))
for path in files:
    try:
        compile(path.read_bytes(), str(path), 'exec')
    except (SyntaxError, ValueError) as exc:
        print(f'Syntax failure {path.relative_to(root)}: {exc}', file=sys.stderr)
        raise SystemExit(2)
print(f'PASS: compiled {len(files)} Python files in memory')
