"""Provider-reported results must be bound to the *requested* mission and immutable Pi entry."""
import json
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

import pytest
from fastapi.testclient import TestClient
from dottie_hill.core import Core
from dottie_hill.service import create_app


class AttributionPi(BaseHTTPRequestHandler):
    async_mode = False
    request_mismatch = False
    entry = 91
    posts = 0
    polls = 0
    mission_id = None

    def log_message(self, *args): pass

    def answer(self, status, body):
        raw = json.dumps(body).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    @classmethod
    def result(cls):
        return {'status': 'done', 'requestId': 'wrong-request' if cls.request_mismatch else cls.mission_id,
                'answer': {'entryId': cls.entry, 'text': 'attributed provider output'}}

    def do_GET(self):
        if self.path.endswith('/agents/main'):
            return self.answer(200, {'config': {'readOnly': True}, 'tools': []})
        if '/submissions/' in self.path:
            type(self).polls += 1
            return self.answer(200, type(self).result())
        return self.answer(404, {'error': 'not found'})

    def do_POST(self):
        body = json.loads(self.rfile.read(int(self.headers['Content-Length'])))
        type(self).mission_id = body['requestId']
        type(self).posts += 1
        if type(self).async_mode:
            return self.answer(202, {'status': 'pending', 'submissionId': 17})
        return self.answer(200, type(self).result())


@pytest.fixture
def pi_endpoint():
    AttributionPi.async_mode = AttributionPi.request_mismatch = False
    AttributionPi.entry = 91
    AttributionPi.posts = AttributionPi.polls = 0
    AttributionPi.mission_id = None
    host = ThreadingHTTPServer(('127.0.0.1', 0), AttributionPi)
    thread = threading.Thread(target=host.serve_forever, daemon=True)
    thread.start()
    yield f'http://127.0.0.1:{host.server_port}'
    host.shutdown()
    host.server_close()
    thread.join(timeout=5)


@pytest.mark.parametrize('async_mode', [False, True])
@pytest.mark.parametrize('invalidity', ['wrong-request', 'missing-entry', 'unsafe-entry'])
def test_unattributable_completed_pi_answer_is_held_not_promoted(tmp_path, monkeypatch, pi_endpoint, async_mode, invalidity):
    """Even an HTTP 200 with answer text is not proof of a valid attributed result."""
    AttributionPi.async_mode = async_mode
    AttributionPi.request_mismatch = invalidity == 'wrong-request'
    AttributionPi.entry = {'wrong-request': 91, 'missing-entry': None, 'unsafe-entry': '../someone-else'}[invalidity]
    monkeypatch.setenv('DOTTIE_PI_TOKEN', 'disposable-test-key')
    core = Core(tmp_path/'state.sqlite', b'v'*32)
    try:
        core.bind_model('operator', 'dottie-hill', {
            'provider': 'pi-durable', 'base_url': pi_endpoint, 'session': 'dottie-private', 'agent': 'main'
        }, 'attribution test')
        mission = core.create_mission('operator', 'dottie-hill', 'inspect', f'attribution:{async_mode}:{invalidity}')
        app = create_app(core, 'operator-test-token', background=False)
        with TestClient(app) as client:
            response = client.post(f"/v1/missions/{mission['mission_id']}/run", headers={
                'Authorization': 'Bearer operator-test-token'})
            assert response.status_code == 200, response.text
            actual = response.json()
            assert actual['status'] == 'UNCERTAIN', actual
            assert not actual.get('answer')
            assert AttributionPi.posts == 1
            if async_mode:
                assert actual['external_submission']['submission_id'] == '17'
                assert AttributionPi.polls >= 1
            assert core.verify_ledger()['valid']
    finally:
        core.close()


@pytest.mark.parametrize('async_mode', [False, True])
def test_valid_pi_answer_retains_exact_entry_attribution(tmp_path, monkeypatch, pi_endpoint, async_mode):
    AttributionPi.async_mode = async_mode
    monkeypatch.setenv('DOTTIE_PI_TOKEN', 'disposable-test-key')
    core = Core(tmp_path/'state.sqlite', b'v'*32)
    try:
        core.bind_model('operator', 'dottie-hill', {
            'provider': 'pi-durable', 'base_url': pi_endpoint, 'session': 'dottie-private', 'agent': 'main'
        }, 'attribution test')
        mission = core.create_mission('operator', 'dottie-hill', 'inspect', f'valid:{async_mode}')
        with TestClient(create_app(core, 'operator-test-token', background=False)) as client:
            response = client.post(f"/v1/missions/{mission['mission_id']}/run", headers={
                'Authorization': 'Bearer operator-test-token'})
            assert response.status_code == 200, response.text
            assert response.json()['status'] == 'DONE', response.text
            assert response.json()['answer']['source_ref'] == 'pi-durable:dottie-private/main/entry:91'
            assert core.verify_ledger()['valid']
    finally:
        core.close()
